struct CrlID {
    std::optional<std::string> crlUrl{};
    std::optional<asn1kit::integer> crlNum{};
    std::optional<asn1kit::utc_date_time> crlTime{};

    static asn1kit::tag default_tag() {
        return asn1kit::tag::sequence;
    }

    static CrlID decode(asn1kit::reader& r, const asn1kit::tag& t = default_tag()) {
        CrlID value{};
        r.with_sequence(t, [&](asn1kit::reader& inner) {
            if (inner.next_is(asn1kit::tag::context(0, true))) {
                std::string tmp_crlUrl{};
                inner.with_explicit(asn1kit::tag::context(0, true), [&](asn1kit::reader& scoped) {
                    tmp_crlUrl = scoped.read_string(asn1kit::tag::ia5_string, asn1kit::string_form::ia5);
                });
                value.crlUrl = std::move(tmp_crlUrl);
            }
            if (inner.next_is(asn1kit::tag::context(1, true))) {
                asn1kit::integer tmp_crlNum{};
                inner.with_explicit(asn1kit::tag::context(1, true), [&](asn1kit::reader& scoped) {
                    tmp_crlNum = scoped.read_integer_value(asn1kit::tag::integer);
                });
                value.crlNum = std::move(tmp_crlNum);
            }
            if (inner.next_is(asn1kit::tag::context(2, true))) {
                asn1kit::utc_date_time tmp_crlTime{};
                inner.with_explicit(asn1kit::tag::context(2, true), [&](asn1kit::reader& scoped) {
                    tmp_crlTime = scoped.read_time(asn1kit::tag::generalized_time, asn1kit::time_form::generalized);
                });
                value.crlTime = std::move(tmp_crlTime);
            }
        });
        return value;
    }

    void encode(asn1kit::writer& w, const asn1kit::tag& t = default_tag()) const {
        auto scope = w.enter_sequence(t);
        if (this->crlUrl.has_value()) {
            {
                auto explicit_scope = w.enter_explicit(asn1kit::tag::context(0, true));
                w.write_string(asn1kit::tag::ia5_string, (*this->crlUrl), asn1kit::string_form::ia5);
            }
        }
        if (this->crlNum.has_value()) {
            {
                auto explicit_scope = w.enter_explicit(asn1kit::tag::context(1, true));
                w.write_integer(asn1kit::tag::integer, (*this->crlNum));
            }
        }
        if (this->crlTime.has_value()) {
            {
                auto explicit_scope = w.enter_explicit(asn1kit::tag::context(2, true));
                w.write_time(asn1kit::tag::generalized_time, (*this->crlTime), asn1kit::time_form::generalized, 3);
            }
        }
    }
};

enum class OCSPResponseStatus {
    successful = 0,
    malformedRequest = 1,
    internalError = 2,
    tryLater = 3,
    sigRequired = 5,
    unauthorized = 6
};

inline void encode_OCSPResponseStatus(asn1kit::writer& w, OCSPResponseStatus value, const asn1kit::tag& t = asn1kit::tag::enumerated) {
    w.write_enumerated_decimal(t, std::to_string(static_cast<std::int32_t>(value)));
}

inline OCSPResponseStatus decode_OCSPResponseStatus(asn1kit::reader& r, const asn1kit::tag& t = asn1kit::tag::enumerated) {
    const auto text = r.read_enumerated_decimal(t);
    const auto number = std::stoll(text);
    if (number == 0) return OCSPResponseStatus::successful;
    if (number == 1) return OCSPResponseStatus::malformedRequest;
    if (number == 2) return OCSPResponseStatus::internalError;
    if (number == 3) return OCSPResponseStatus::tryLater;
    if (number == 5) return OCSPResponseStatus::sigRequired;
    if (number == 6) return OCSPResponseStatus::unauthorized;
    throw asn1kit::exception("Unknown ENUMERATED value.");
}

