enum class ExtendedCertificateOrCertificate_kind {
    certificate,
    extendedCertificate
};

struct ExtendedCertificateOrCertificate {
    ExtendedCertificateOrCertificate_kind kind{};
    std::variant<::asn1kit::modern::PKIX1Explicit2009::Certificate, ExtendedCertificate> value{};

    static ExtendedCertificateOrCertificate from_certificate(::asn1kit::modern::PKIX1Explicit2009::Certificate v) {
        ExtendedCertificateOrCertificate result{};
        result.kind = ExtendedCertificateOrCertificate_kind::certificate;
        result.value = std::move(v);
        return result;
    }

    static ExtendedCertificateOrCertificate from_extendedCertificate(ExtendedCertificate v) {
        ExtendedCertificateOrCertificate result{};
        result.kind = ExtendedCertificateOrCertificate_kind::extendedCertificate;
        result.value = std::move(v);
        return result;
    }

    static asn1kit::tag default_tag() {
        throw asn1kit::exception("Untagged CHOICE has no default_tag.");
    }

    static ExtendedCertificateOrCertificate decode(asn1kit::reader& r) {
        asn1kit::tag peeked;
        if (!r.try_peek_tag(peeked)) throw asn1kit::exception("Expected CHOICE alternative.");
        if (peeked.matches_ignore_constructed(asn1kit::tag::sequence)) {
            ExtendedCertificateOrCertificate result{};
            result.kind = ExtendedCertificateOrCertificate_kind::certificate;
            ::asn1kit::modern::PKIX1Explicit2009::Certificate alt{};
            alt = ::asn1kit::modern::PKIX1Explicit2009::Certificate::decode(r, asn1kit::tag::sequence);
            result.value = std::move(alt);
            return result;
        } else if (peeked.matches_ignore_constructed(asn1kit::tag::context(0, true))) {
            ExtendedCertificateOrCertificate result{};
            result.kind = ExtendedCertificateOrCertificate_kind::extendedCertificate;
            ExtendedCertificate alt{};
            alt = ExtendedCertificate::decode(r, asn1kit::tag::context(0, true));
            result.value = std::move(alt);
            return result;
        } else {
            throw asn1kit::exception("Unknown CHOICE alternative.");
        }
    }

    static ExtendedCertificateOrCertificate decode(asn1kit::reader& r, const asn1kit::tag& t) {
        (void)t;
        return decode(r);
    }

    void encode(asn1kit::writer& w) const {
        switch (kind) {
        case ExtendedCertificateOrCertificate_kind::certificate:
            {
                const auto& alt = std::get<0>(value);
                alt.encode(w, asn1kit::tag::sequence);
                break;
            }
        case ExtendedCertificateOrCertificate_kind::extendedCertificate:
            {
                const auto& alt = std::get<1>(value);
                alt.encode(w, asn1kit::tag::context(0, true));
                break;
            }
        }
    }

    void encode(asn1kit::writer& w, const asn1kit::tag& t) const {
        (void)t;
        encode(w);
    }
};

