enum class RevocationInfoChoice_kind {
    crl,
    other,
    unknown
};

struct RevocationInfoChoice {
    RevocationInfoChoice_kind kind{};
    std::variant<::asn1kit::modern::PKIX1Explicit2009::CertificateList, OtherRevocationInfoFormat> value{};
    std::optional<asn1kit::any> unknown{};

    static RevocationInfoChoice from_crl(::asn1kit::modern::PKIX1Explicit2009::CertificateList v) {
        RevocationInfoChoice result{};
        result.kind = RevocationInfoChoice_kind::crl;
        result.value = std::move(v);
        return result;
    }

    static RevocationInfoChoice from_other(OtherRevocationInfoFormat v) {
        RevocationInfoChoice result{};
        result.kind = RevocationInfoChoice_kind::other;
        result.value = std::move(v);
        return result;
    }

    static RevocationInfoChoice from_unknown(asn1kit::any v) {
        RevocationInfoChoice result{};
        result.kind = RevocationInfoChoice_kind::unknown;
        result.unknown = std::move(v);
        return result;
    }

    static asn1kit::tag default_tag() {
        throw asn1kit::exception("Untagged CHOICE has no default_tag.");
    }

    static RevocationInfoChoice decode(asn1kit::reader& r) {
        asn1kit::tag peeked;
        if (!r.try_peek_tag(peeked)) throw asn1kit::exception("Expected CHOICE alternative.");
        if (peeked.matches_ignore_constructed(asn1kit::tag::sequence)) {
            RevocationInfoChoice result{};
            result.kind = RevocationInfoChoice_kind::crl;
            ::asn1kit::modern::PKIX1Explicit2009::CertificateList alt{};
            alt = ::asn1kit::modern::PKIX1Explicit2009::CertificateList::decode(r, asn1kit::tag::sequence);
            result.value = std::move(alt);
            return result;
        } else if (peeked.matches_ignore_constructed(asn1kit::tag::context(1, true))) {
            RevocationInfoChoice result{};
            result.kind = RevocationInfoChoice_kind::other;
            OtherRevocationInfoFormat alt{};
            alt = OtherRevocationInfoFormat::decode(r, asn1kit::tag::context(1, true));
            result.value = std::move(alt);
            return result;
        } else {
            return from_unknown(r.read_any());
        }
    }

    static RevocationInfoChoice decode(asn1kit::reader& r, const asn1kit::tag& t) {
        (void)t;
        return decode(r);
    }

    void encode(asn1kit::writer& w) const {
        switch (kind) {
        case RevocationInfoChoice_kind::crl:
            {
                const auto& alt = std::get<0>(value);
                alt.encode(w, asn1kit::tag::sequence);
                break;
            }
        case RevocationInfoChoice_kind::other:
            {
                const auto& alt = std::get<1>(value);
                alt.encode(w, asn1kit::tag::context(1, true));
                break;
            }
        case RevocationInfoChoice_kind::unknown:
            if (!unknown.has_value()) throw asn1kit::exception("Missing unknown CHOICE value.");
            w.write_any(*unknown);
            break;
        }
    }

    void encode(asn1kit::writer& w, const asn1kit::tag& t) const {
        (void)t;
        encode(w);
    }
};

