template <typename T>
struct parameters_binding {
    asn1kit::oid key{};

    [[nodiscard]] bool try_decode(const AttributeCertificateV1_AlgorithmIdentifier& src, const AttributeCertificateV1& parent0, T& out) const {
        if (!src.parameters.has_value()) return false;
        if (!(parent0.algorithmIdentifier.algorithm == key)) return false;
        out = asn1kit::decode_open<T>(*src.parameters);
        return true;
    }

    void set(AttributeCertificateV1_AlgorithmIdentifier& src, const AttributeCertificateV1& parent0, const T& value) const {
        if (!(parent0.algorithmIdentifier.algorithm == key)) {
            throw asn1kit::exception("Enclosing selector does not match the open-type binding.");
        }
        src.parameters = asn1kit::encode_open(value);
    }
};

template <typename T>
struct signature_binding {
    asn1kit::oid key{};

    [[nodiscard]] bool try_decode(const AttributeCertificateV1& src, T& out) const {
        if (!(src.algorithmIdentifier.algorithm == key)) return false;
        out = asn1kit::decode_contained<T>(src.signature);
        return true;
    }

    void set(AttributeCertificateV1& src, const T& value) const {
        src.algorithmIdentifier.algorithm = key;
        src.signature = asn1kit::encode_contained(value);
    }

    [[nodiscard]] AttributeCertificateV1 create(const T& value) const {
        AttributeCertificateV1 src{};
        set(src, value);
        return src;
    }
};

